/* EntoTools — shared helpers for the Degree Day Calculator, GDD Lookup and
 * Sample Collection pages. Single source of truth for HTML escaping and the
 * modified Growing Degree Day (mGDD) calculation, so the three pages can never
 * drift apart.
 *
 * This file is NOT generated by scripts/build-public.sh — edit it here.
 * Load it before each page's inline <script>. Exposes globals:
 *   esc(str)
 *   computeGDD(temperatures, baseTemp, accumStartMD, maxTemp)
 */
(function (global) {
    'use strict';

    // HTML-escape a value by round-tripping through a text node so any
    // user/API-supplied string is safe to drop into innerHTML. Quotes are
    // escaped too, so the result is also safe inside an attribute value
    // (e.g. data-description="…") — a text-node round-trip alone leaves them.
    function esc(str) {
        const el = document.createElement('span');
        el.textContent = str == null ? '' : str;
        return el.innerHTML.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    // Modified Growing Degree Days.
    //   accumStartMD = 'MM-DD' (season start; days before it each year hold 0)
    //   baseTemp / maxTemp are the lower/upper cutoffs in °F (maxTemp default 86)
    // Returns one record per day: { date, md, avg, daily, cumulative, TMIN, TMAX,
    // PRCP, is_forecast, is_calculated }.
    function computeGDD(temperatures, baseTemp, accumStartMD, maxTemp) {
        maxTemp = maxTemp != null ? maxTemp : 86;
        // Clone each record first: the gap-fill interpolation below writes TMIN/
        // TMAX, and the caller's objects are shared with the tables/charts/cache,
        // so mutating them in place would leak interpolated values into other views.
        const sorted = (temperatures || [])
            .map((t) => ({ ...t }))
            .sort((a, b) => a.date.localeCompare(b.date));

        // Pre-pass: interpolate missing data across multi-day gaps. For each gap
        // of missing days, find the nearest known day before and after and
        // linearly interpolate all days in between.
        let i = 0;
        while (i < sorted.length) {
            if (sorted[i].TMIN !== null && sorted[i].TMAX !== null) { i++; continue; }
            const gapStart = i;
            const prev = gapStart > 0 ? sorted[gapStart - 1] : null;
            while (i < sorted.length && (sorted[i].TMIN === null || sorted[i].TMAX === null)) { i++; }
            const next = i < sorted.length ? sorted[i] : null;
            if (prev && next && prev.TMIN !== null && prev.TMAX !== null && next.TMIN !== null && next.TMAX !== null) {
                const gapLen = i - gapStart;
                for (let g = 0; g < gapLen; g++) {
                    const t = sorted[gapStart + g];
                    const frac = (g + 1) / (gapLen + 1);
                    t.TMIN = Math.round((prev.TMIN + (next.TMIN - prev.TMIN) * frac) * 10) / 10;
                    t.TMAX = Math.round((prev.TMAX + (next.TMAX - prev.TMAX) * frac) * 10) / 10;
                    t.is_calculated = true;
                    console.log('[Ento:computeGDD] interpolated missing data for', t.date, '→ TMIN:', t.TMIN, 'TMAX:', t.TMAX, '(gap', g + 1, '/' + gapLen + ')');
                }
            }
        }

        let cumulative = 0;
        let prevYear = null;
        const results = [];
        for (const t of sorted) {
            const dateYear = t.date.slice(0, 4);
            const dateMD = t.date.slice(5); // 'MM-DD'

            // Cumulative restarts each calendar year.
            if (prevYear !== null && dateYear !== prevYear) cumulative = 0;
            prevYear = dateYear;

            // Accumulation only counts on/after the season start; earlier days hold 0.
            const isActive = dateMD >= accumStartMD;

            let daily = 0;
            if (isActive && t.TMIN !== null && t.TMAX !== null) {
                const cappedMax = Math.min(t.TMAX, maxTemp);
                const cappedMin = Math.max(t.TMIN, baseTemp);
                daily = Math.max(0, (cappedMax + cappedMin) / 2 - baseTemp);
            }
            cumulative = isActive ? cumulative + daily : 0;

            results.push({
                date: t.date,
                md: dateMD,
                avg: (t.TMIN !== null && t.TMAX !== null) ? Math.round(((t.TMAX + t.TMIN) / 2) * 10) / 10 : null,
                daily: Math.round(daily * 10) / 10,
                cumulative: Math.round(cumulative * 10) / 10,
                TMIN: t.TMIN,
                TMAX: t.TMAX,
                PRCP: t.PRCP != null ? t.PRCP : null,
                is_forecast: t.is_forecast || false,
                is_calculated: t.is_calculated || false,
            });
        }
        console.log('[Ento:computeGDD] computed', results.length, 'GDD records, final cumulative:', results.length ? results[results.length - 1].cumulative : 0);
        return results;
    }

    global.esc = esc;
    global.computeGDD = computeGDD;
})(window);
